    (0.000 0.060 0.000)   // 3
    (0.000 0.000 0.040)   // 4
    (0.100 0.000 0.040)   // 5
    (0.100 0.060 0.040)   // 6
    (0.000 0.060 0.040)   // 7
);

blocks
(
    hex (0 1 2 3 4 5 6 7) (25 15 10) simpleGrading (1 1 1)
);

boundary
(
